import test from 'node:test';
import assert from 'node:assert/strict';
import {planReadiness,planFingerprint} from '../../reda-2/plan-readiness.mjs';
const p={schema:6,context:{stage:'build',capacity:'standard',equipment:'home',floorOK:false,band:false,trainingHistory:'regular'},goal:'Klara trappan',exercises:[{id:'chair',dose:{sets:2,reps:8}}],schedule:{days:[1,3,5]},reviewDate:'2026-10-01',warnings:[]};
const input={patient:{id:'patient-a'},profile:{focus:'Knä',email:'fixture@example.test'},plan:p,saved:{payload:p},reviewed:planFingerprint(p)};
const step=(s,id)=>s.steps.find(x=>x.id===id);
test('a saved draft is not delivered or started; closed activation does not point to a future task',()=>{const s=planReadiness(input);assert.equal(s.ready,true);assert.equal(step(s,'handover').state,'blocked');assert.equal(step(s,'first_session').state,'todo');assert.equal(s.next,null)});
test('meaningful changes invalidate both review and saved state; key order does not',()=>{const s=planReadiness({...input,plan:{...p,goal:'Ett annat mål'}});assert.equal(step(s,'saved').state,'todo');assert.equal(step(s,'review').state,'todo');assert.equal(planFingerprint({...p,context:{...p.context}}),planFingerprint(p));assert.notEqual(planFingerprint({...p,schedule:{days:[2,4]}}),planFingerprint(p))});
test('only matching current plan evidence completes the patient journey',()=>{const active={id:'active-a',payload:p};let s=planReadiness({...input,active,sessions:[{plan_id:'old',status:'completed'}],responses:[{plan_id:'old'}]});assert.equal(step(s,'first_session').state,'todo');assert.equal(step(s,'response').state,'todo');s=planReadiness({...input,active,sessions:[{plan_id:'active-a',status:'completed'}],responses:[{plan_id:'active-a'}]});assert.equal(step(s,'first_session').state,'done');assert.equal(step(s,'response').state,'done');s=planReadiness({...input,plan:{...p,goal:'Nytt mål'},active,sessions:[{plan_id:'active-a',status:'completed'}]});assert.equal(step(s,'first_session').state,'todo')});
test('worksheet has two preparation steps; clinic print does not claim actual handover',()=>{const sheet=planReadiness({audience:'worksheet',plan:{...p,goal:'',reviewDate:''},reviewed:''});assert.equal(sheet.total,2);assert.equal(step(sheet,'review').state,'todo');const clinic=planReadiness({...input,deliveryMode:'clinic',profile:{focus:'Knä'}});assert.equal(clinic.ready,true);assert.equal(step(clinic,'contact'),undefined);assert.equal(step(clinic,'handover').state,'todo');assert.equal(step(clinic,'first_session'),undefined)});
test('remote assessment issues and plan warnings remain outstanding despite saved content',()=>{const s=planReadiness({...input,careIssues:['Bedömning saknas'],checks:['Dos behöver kompletteras']});assert.equal(step(s,'followup').state,'todo');assert.equal(step(s,'plan').state,'todo');assert.equal(s.ready,false)});
test('self flow needs explicit input; rehab stops automatic preparation; extras do not inflate completion',()=>{let s=planReadiness({audience:'self',plan:p,reviewed:planFingerprint(p),selfConfirmed:true});assert.equal(s.total,3);assert.equal(s.ready,true);s=planReadiness({audience:'self',plan:p,reviewed:planFingerprint(p),selfConfirmed:true,selfNeedsAssessment:true});assert.equal(step(s,'context').state,'blocked');assert.equal(s.ready,false);assert.equal(s.steps.some(x=>x.id==='saved'),false)});
